// HostSession::dispatch: sequence != 0; else returns HostDispatchError::sequence_zero.
[[nodiscard]] constexpr bool admits_dispatch_sequence(const std::uint64_t sequence) noexcept {
    const bool result = sequence != 0;
    return result;
}

// HostSession::dispatch: sequence > last_sequence; else returns HostDispatchError::non_monotonic_sequence.
[[nodiscard]] constexpr bool admits_dispatch_order(const std::uint64_t sequence, const std::uint64_t last_sequence) noexcept {
    const bool result = sequence > last_sequence;
    return result;
}

// HostSession::dispatch: (phase != phase_constructed or attach != 0 or shutdown != 0) and (phase != phase_attached or
// attach == 0) and (phase != phase_close_authorized or closed != 0 or shutdown != 0 or passive_terminal != 0) and
// (phase != phase_closed or shutdown != 0); else returns HostDispatchError::invalid_lifecycle.
[[nodiscard]] constexpr bool admits_dispatch_lifecycle(const bool attach, const bool shutdown, const bool closed, const bool passive_terminal, const HostLifecyclePhase phase) noexcept {
    const bool result = ((phase != HostLifecyclePhase::constructed) || (attach != 0) || (shutdown != 0))
                     && ((phase != HostLifecyclePhase::attached) || (attach == 0))
                     && ((phase != HostLifecyclePhase::close_authorized) || (closed != 0) || (shutdown != 0) || (passive_terminal != 0))
                     && ((phase != HostLifecyclePhase::closed) || (shutdown != 0));
    return result;
}

// HostSession::dispatch: finite(width) and finite(height) and width > 0 and height > 0; else returns
// HostDispatchError::invalid_geometry.
[[nodiscard]] constexpr bool admits_dispatch_size(const double width, const double height) noexcept {
    const bool result = __builtin_isfinite(width) && __builtin_isfinite(height) && (width > 0) && (height > 0);
    return result;
}

// HostSession::dispatch: finite(scale) and scale > 0; else returns HostDispatchError::invalid_geometry.
[[nodiscard]] constexpr bool admits_dispatch_scale(const double scale) noexcept {
    const bool result = __builtin_isfinite(scale) && (scale > 0);
    return result;
}

